-- Each new event gets at least one primary-text citation, keyed by the era it sits in.
INSERT INTO event_sources(event_id,source_id)
SELECT e.id,s.id FROM events e
JOIN chapters ch ON ch.id=e.chapter_id
JOIN (VALUES
  ('primeval','Genesis'),('patriarchs','Genesis'),('exodus-and-sinai','Exodus'),
  ('wilderness-and-conquest','Numbers'),('wilderness-and-conquest','Joshua'),
  ('judges','Judges'),('judges','Ruth'),
  ('united-monarchy','Samuel'),('divided-kingdoms','Kings'),
  ('prophetic-narrative','Jonah'),('prophetic-narrative','Isaiah'),
  ('judah-and-exile','Kings'),('judah-and-exile','Jeremiah'),('judah-and-exile','Daniel'),
  ('return-and-restoration','Ezra'),('return-and-restoration','Esther'),('return-and-restoration','Nehemiah'),
  ('gospels','Gospel according to Luke'),('gospels','Gospel according to Mark'),
  ('acts','Acts of the Apostles'),('pauline-mission','Acts of the Apostles')
) AS v(chapter_slug,source_title) ON v.chapter_slug=ch.slug
JOIN sources s ON s.title=v.source_title AND s.work_id=e.work_id
WHERE e.work_id='10000000-0000-4000-8000-000000000005' AND e.id::text LIKE '62000000%'
ON CONFLICT DO NOTHING;

