INSERT INTO route_translations(route_id,locale,name,summary,status)
SELECT r.id,v.locale::locale_code,v.name,v.summary,'published' FROM routes r JOIN (VALUES
('joseph-into-egypt','zh-CN','约瑟入埃及','从迦南到尼罗河三角洲的路线。'),('joseph-into-egypt','en','Joseph into Egypt','The route from Canaan to the Nile delta.'),
('wilderness-to-jordan','zh-CN','旷野到约旦河','西奈、加低斯、尼波山到渡河点的推定路线。'),('wilderness-to-jordan','en','Wilderness to the Jordan','The inferred route from Sinai through Kadesh and Nebo to the crossing.'),
('jonah-flight-and-mission','zh-CN','约拿的逃避与使命','约帕、他施方向与尼尼微构成的反向行程。'),('jonah-flight-and-mission','en','Jonah’s flight and mission','Joppa, the Tarshish direction, and Nineveh form a reversed itinerary.'),
('deportation-to-babylon','zh-CN','被掳往巴比伦','耶路撒冷到巴比伦的流放路线。'),('deportation-to-babylon','en','Deportation to Babylon','The route of deportation from Jerusalem to Babylon.'),
('nativity-and-return','zh-CN','诞生叙事的行程','拿撒勒、伯利恒、埃及与返回拿撒勒。'),('nativity-and-return','en','Nativity itinerary','Nazareth, Bethlehem, Egypt, and the return to Nazareth.'),
('second-missionary-journey','zh-CN','第二次宣教旅程','安提阿出发，经腓立比、雅典到哥林多。'),('second-missionary-journey','en','Second missionary journey','From Antioch through Philippi and Athens to Corinth.'),
('voyage-to-rome','zh-CN','前往罗马的航程','该撒利亚、马耳他到罗马的海路。'),('voyage-to-rome','en','Voyage to Rome','The sea route from Caesarea via Malta to Rome.')
) AS v(slug,locale,name,summary) ON r.slug=v.slug AND r.work_id='10000000-0000-4000-8000-000000000005';

